window.A1_RADIO_RECORDINGS={base:new URL("audio/radio/",document.currentScript?.src||new URL("../shared/radio-recordings.js",document.baseURI).href).href,entries:{"15670835":{"file":"deutsch/lesson-04-2-15670835.mp3","signature":"[\"de\",[[\"A\",\"Hallo, hier ist Anna. Unser Treffen ist am Freitag im Juli. Wir treffen uns um halb fünf, also um sechzehn Uhr dreißig. Am Sonntag habe ich keine Zeit. Bis Freitag!\",\"female\"]]]"},"34208392":{"file":"francais/lesson-07-1-34208392.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, je voudrais deux kilos de pommes et trois cents grammes de fromage. Les pommes coûtent quatre euros. Le fromage coûte six euros cinquante. Ça fait dix euros cinquante. Je paie par carte.\",\"female\"]]]"},"84720232":{"file":"englisch/lesson-08-2-84720232.mp3","signature":"[\"en\",[[\"B\",\"Our class designed a container which keeps food cool without electricity. It wasn't invented by us; similar designs have been used for years. We built ours from two clay pots with wet sand between them. The first version leaked, so the teacher helped us change the base. It works best in dry weather. We learned more from the failed first attempt than from simply following instructions perfectly.\",\"male\"]]]"},"397cbe51":{"file":"francais/lesson-01-1-397cbe51.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour. Comment vous vous appelez ?\",\"female\"],[\"B\",\"Je m’appelle Luc.\",\"male\"],[\"A\",\"Vous venez d’où ?\",\"female\"],[\"B\",\"Je viens de Paris. Maintenant, j’habite à Berlin.\",\"male\"],[\"A\",\"Vous parlez français ?\",\"female\"],[\"B\",\"Oui, je parle français et un peu allemand. Au revoir !\",\"male\"]]]"},"56af90af":{"file":"francais/lesson-01-2-56af90af.mp3","signature":"[\"fr\",[[\"A\",\"Bonsoir, Madame. Comment allez-vous ?\",\"male\"],[\"B\",\"Ça va bien, merci. Je m’appelle Léa. Et vous ?\",\"female\"],[\"A\",\"Je m’appelle Marc. Enchanté !\",\"male\"],[\"B\",\"Enchantée ! Au revoir, Monsieur.\",\"female\"]]]"},"06941a97":{"file":"francais/lesson-02-1-06941a97.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour. Votre prénom, s’il vous plaît ?\",\"male\"],[\"B\",\"Zoé. Zoé s’écrit zède, o, e accent aigu.\",\"female\"],[\"A\",\"Et votre nom de famille ?\",\"male\"],[\"B\",\"Morel. M, O, R, E, L.\",\"female\"],[\"A\",\"Vous habitez où ?\",\"male\"],[\"B\",\"J’habite à Lille.\",\"female\"]]]"},"52796f7e":{"file":"francais/lesson-02-2-52796f7e.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour. Votre prénom et votre nom, s’il vous plaît ?\",\"female\"],[\"B\",\"Je m’appelle François Blanc.\",\"male\"],[\"A\",\"Vous pouvez épeler ?\",\"female\"],[\"B\",\"François s’écrit F, R, A, N, C cédille, O, I, S. Blanc s’écrit B, L, A, N, C.\",\"male\"],[\"A\",\"Quelle est votre adresse ?\",\"female\"],[\"B\",\"Pouvez-vous parler plus lentement, s’il vous plaît ?\",\"male\"],[\"A\",\"Votre adresse, s’il vous plaît.\",\"female\"],[\"B\",\"Rue Victor-Hugo à Paris.\",\"male\"]]]"},"0308fd20":{"file":"francais/lesson-03-1-0308fd20.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, c’est Nina. Je voudrais donner mes informations pour le cours.\",\"female\"],[\"B\",\"Bonjour Nina. Vous avez trente-six ans ?\",\"male\"],[\"A\",\"Non, j’ai vingt-six ans, pas trente-six.\",\"female\"],[\"B\",\"Votre téléphone, s’il vous plaît ?\",\"male\"],[\"A\",\"Zéro six, douze, quarante, cinquante-huit, soixante-treize.\",\"female\"],[\"B\",\"Merci. Et votre code postal ?\",\"male\"],[\"A\",\"B, trois, V, un, L, deux.\",\"female\"]]]"},"fb6c007f":{"file":"francais/lesson-03-2-fb6c007f.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour Paul. Quel est votre jour de naissance ?\",\"female\"],[\"B\",\"Je suis né le dix-sept avril.\",\"male\"],[\"A\",\"Merci. Et votre téléphone ?\",\"female\"],[\"B\",\"Zéro sept, quatre-vingt-deux, seize, quatre-vingt-onze, vingt-quatre.\",\"male\"],[\"A\",\"Vous êtes combien dans votre cours ?\",\"female\"],[\"B\",\"Dans notre cours, nous sommes trente et un étudiants.\",\"male\"]]]"},"f0da2ab7":{"file":"francais/lesson-04-1-f0da2ab7.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour Léa, c’est Marc. Le rendez-vous n’est pas mardi. On se voit mercredi, le quinze juillet, à neuf heures moins le quart, devant la gare. Je suis libre à partir de huit heures et demie.\",\"male\"]]]"},"c2984e19":{"file":"francais/lesson-04-2-c2984e19.mp3","signature":"[\"fr\",[[\"A\",\"Le cours de français commence le lundi douze janvier à quatorze heures et quart. Le vendredi, le cours commence à quinze heures. Il n’y a pas de cours le dimanche.\",\"female\"]]]"},"6774601f":{"file":"francais/lesson-05-1-6774601f.mp3","signature":"[\"fr\",[[\"A\",\"Je m’appelle Emma. J’ai deux frères et une sœur. Ma sœur s’appelle Julie et elle a vingt ans. Mes parents habitent à Montréal. Moi, j’habite à Lyon et je suis célibataire.\",\"female\"]]]"},"7d1ab24c":{"file":"francais/lesson-05-2-7d1ab24c.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, je suis Paul. Ma femme s’appelle Anna. Nous avons deux enfants : Marie a six ans et Luc a huit ans. Ma mère et mon père habitent à Paris. Anna est calme et très sympa.\",\"male\"]]]"},"7796da81":{"file":"francais/lesson-06-1-7796da81.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, je voudrais une soupe sans viande et une salade. Pour boire, de l’eau, s’il vous plaît. Pas de café. Comme dessert, je prends une glace au chocolat. Mon plat préféré, c’est la pizza.\",\"female\"]]]"},"c34d29fa":{"file":"francais/lesson-06-2-c34d29fa.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, qu’est-ce que vous prenez ?\",\"male\"],[\"B\",\"Je voudrais un café sans sucre et un croissant, s’il vous plaît.\",\"female\"],[\"A\",\"Bien sûr. Le café coûte deux euros et le croissant coûte trois euros.\",\"male\"],[\"B\",\"Merci. L’addition, s’il vous plaît.\",\"female\"]]]"},"e6562a7e":{"file":"francais/lesson-07-2-e6562a7e.mp3","signature":"[\"fr\",[[\"A\",\"Ce pantalon existe en taille quarante et quarante-deux. La taille trente-huit n’est pas disponible. Le pantalon coûte vingt-neuf euros quatre-vingt-dix. Vous pouvez payer par carte ou en espèces.\",\"male\"]]]"},"449f38a2":{"file":"francais/lesson-08-1-449f38a2.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, l’appartement est au douze rue Victor-Hugo, près du centre. Il a deux pièces et une cuisine. Le loyer est de six cent cinquante euros par mois. Il n’y a pas de balcon.\",\"male\"]]]"},"8a7ee3d2":{"file":"francais/lesson-08-2-8a7ee3d2.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, je peux visiter l’appartement quand ?\",\"female\"],[\"B\",\"Jeudi à dix-sept heures.\",\"male\"],[\"A\",\"Sur la photo, où est la table ?\",\"female\"],[\"B\",\"La table est dans la cuisine. La lampe est sur la table.\",\"male\"],[\"A\",\"Et le sac ?\",\"female\"],[\"B\",\"Le sac est sous la table. Il y a aussi un lit dans la chambre.\",\"male\"]]]"},"a1ccfbd0":{"file":"francais/lesson-09-1-a1ccfbd0.mp3","signature":"[\"fr\",[[\"A\",\"Pour aller à la gare, allez tout droit, puis tournez à droite après la pharmacie. La gare est à cinq minutes à pied. Pour le musée, prenez le bus huit, pas le bus trois.\",\"male\"]]]"},"6a2467a1":{"file":"francais/lesson-09-2-6a2467a1.mp3","signature":"[\"fr\",[[\"A\",\"Attention, le train pour Lyon part du quai quatre, et non du quai deux. Le départ est à dix heures vingt. Le train pour Paris a dix minutes de retard. Pour Paris, allez au quai six.\",\"female\"]]]"},"1be88d12":{"file":"francais/lesson-10-1-1be88d12.mp3","signature":"[\"fr\",[[\"A\",\"Je m’appelle Julie. Je suis étudiante. Le lundi et le mercredi, mon cours commence à neuf heures. Le vendredi, il commence à dix heures. Je travaille dans un café le samedi.\",\"female\"]]]"},"04d01d54":{"file":"francais/lesson-10-2-04d01d54.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, je suis Marc, je suis médecin. Je travaille du lundi au jeudi, de huit heures à seize heures. Le vendredi, je ne travaille pas. Mon bureau est près de la gare.\",\"male\"]]]"},"78ef20e2":{"file":"francais/lesson-11-1-78ef20e2.mp3","signature":"[\"fr\",[[\"A\",\"Le lundi, je me lève à six heures et demie. D’abord, je prends le petit-déjeuner. Puis je prends le bus à sept heures et quart. Je rentre à dix-huit heures, mais le vendredi, je rentre à seize heures.\",\"male\"]]]"},"afe4eaa6":{"file":"francais/lesson-11-2-afe4eaa6.mp3","signature":"[\"fr\",[[\"A\",\"Salut, c’est Léa. Maintenant, je suis en train de travailler. D’habitude, je déjeune à midi. Aujourd’hui, je déjeune à treize heures. Le soir, je regarde la télé et je me couche à vingt-trois heures.\",\"female\"]]]"},"5fd71942":{"file":"francais/lesson-12-1-5fd71942.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, je voudrais un rendez-vous avec le médecin. J’ai mal à la tête depuis mardi. Je n’ai pas de fièvre. Je suis libre jeudi matin, mais pas jeudi après-midi.\",\"female\"]]]"},"6e8faeb7":{"file":"francais/lesson-12-2-6e8faeb7.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, je voudrais un médicament contre le rhume.\",\"female\"],[\"B\",\"Bonjour. Voici votre médicament. La consigne est : deux fois par jour, le matin et le soir, pendant trois jours.\",\"male\"],[\"A\",\"Pardon, pouvez-vous répéter ?\",\"female\"],[\"B\",\"Deux fois par jour, le matin et le soir, pendant trois jours.\",\"male\"]]]"},"356dc1ec":{"file":"francais/lesson-13-1-356dc1ec.mp3","signature":"[\"fr\",[[\"A\",\"Aujourd’hui, il pleut à Lyon et il fait douze degrés. Prenez un parapluie et une veste. Demain, il va faire beau, avec vingt degrés. Il va y avoir du vent le soir.\",\"female\"]]]"},"81aa2379":{"file":"francais/lesson-13-2-81aa2379.mp3","signature":"[\"fr\",[[\"A\",\"Pour notre sortie samedi, je prends une petite veste bleue et un pantalon noir. Ma sœur prend une veste rouge. C’est le printemps, et le matin il fait encore froid.\",\"male\"]]]"},"4762d779":{"file":"francais/lesson-14-1-4762d779.mp3","signature":"[\"fr\",[[\"A\",\"Le samedi, je joue au tennis avec Julie. Le dimanche, je préfère lire à la maison. Julie adore le cinéma, mais moi, je n’aime pas les films d’action. Ce soir, nous allons au cinéma.\",\"female\"]]]"},"2b2b7cbc":{"file":"francais/lesson-14-2-2b2b7cbc.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, je m’appelle Marc. J’adore la cuisine et je fais du sport le dimanche. Je ne joue pas au football. Le vendredi soir, je vais au cinéma avec mon frère, pas avec mes collègues.\",\"male\"]]]"},"f3049dfc":{"file":"francais/lesson-15-1-f3049dfc.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, je voudrais réserver une chambre pour deux personnes du dix au douze juillet, pour deux nuits. Nous allons arriver le dix juillet à dix-neuf heures. Est-ce que le petit-déjeuner est inclus ?\",\"female\"]]]"},"697ed979":{"file":"francais/lesson-15-2-697ed979.mp3","signature":"[\"fr\",[[\"A\",\"Votre train pour Paris part à huit heures quarante du quai six. Le billet aller simple coûte vingt euros. L’aller-retour coûte trente-six euros. Le retour est vendredi.\",\"male\"]]]"},"4b4d4e07":{"file":"francais/lesson-16-1-4b4d4e07.mp3","signature":"[\"fr\",[[\"A\",\"Salut Léa, merci pour ton invitation samedi. Je suis désolé, je ne peux pas venir à dix-huit heures. Je vais arriver à dix-neuf heures et demie. Je peux apporter un dessert. À samedi !\",\"male\"]]]"},"f0a3f73d":{"file":"francais/lesson-16-2-f0a3f73d.mp3","signature":"[\"fr\",[[\"A\",\"Allô Paul, c’est Anna. Je ne peux pas venir au cinéma vendredi, j’ai déjà un rendez-vous. On peut aller au cinéma dimanche à seize heures. Tu peux me rappeler demain ? Et aujourd’hui, c’est mon anniversaire !\",\"female\"],[\"B\",\"Oui, avec plaisir. Et bon anniversaire !\",\"male\"]]]"},"d80a3d99":{"file":"francais/lesson-17-1-d80a3d99.mp3","signature":"[\"fr\",[[\"A\",\"Pour votre inscription, écrivez votre nom de famille dans la première case et votre prénom dans la deuxième. La signature est en bas du formulaire. Apportez le formulaire lundi au secrétariat, pas par courriel.\",\"male\"]]]"},"bcc0e2a2":{"file":"francais/lesson-17-2-bcc0e2a2.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour. Pour le formulaire, votre nom et votre prénom, s’il vous plaît.\",\"male\"],[\"B\",\"Bonjour, je suis Léa Martin.\",\"female\"],[\"A\",\"Votre date de naissance ?\",\"male\"],[\"B\",\"Je suis née le trois mai. Je suis allemande.\",\"female\"],[\"A\",\"Et votre adresse électronique ? Vous pouvez épeler ?\",\"male\"],[\"B\",\"l, e, a, point, m, a, r, t, i, n, arobase, e, x, e, m, p, l, e, point, f, r.\",\"female\"],[\"A\",\"Merci, Léa Martin.\",\"male\"]]]"},"380643e5":{"file":"francais/lesson-18-1-380643e5.mp3","signature":"[\"fr\",[[\"A\",\"Excusez-moi, je ne comprends pas le dernier mot. Pouvez-vous le répéter plus lentement et l’écrire, s’il vous plaît ? Je comprends la première phrase. Je n’ai pas de stylo.\",\"female\"]]]"},"7f53e6fb":{"file":"francais/lesson-18-2-7f53e6fb.mp3","signature":"[\"fr\",[[\"A\",\"Le cours est dans la salle douze, au premier étage. Pardon, pourriez-vous répéter le numéro ? Oui, salle douze, pas salle deux. Le cours commence à quinze heures.\",\"female\"]]]"},"c0528816":{"file":"francais/lesson-19-1-c0528816.mp3","signature":"[\"fr\",[[\"A\",\"Voici le centre de notre ville. À gauche, c’est un hôtel. À droite, c’est le musée. La gare est derrière le musée. Les deux cafés sont devant l’hôtel, pas derrière.\",\"male\"]]]"},"07b38d53":{"file":"francais/lesson-19-2-07b38d53.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, je voudrais une baguette, deux cafés et trois croissants. Les croissants sont pour mes enfants. Les cafés sont pour mon mari et moi. La baguette est pour notre déjeuner.\",\"female\"]]]"},"0229e38d":{"file":"francais/lesson-20-1-0229e38d.mp3","signature":"[\"fr\",[[\"A\",\"Je travaille du lundi au jeudi. Le vendredi, je ne travaille pas. Je n’ai pas de voiture, alors je prends le bus. Le soir, je ne regarde jamais la télévision. Je préfère lire.\",\"male\"]]]"},"afc4a65f":{"file":"francais/lesson-20-2-afc4a65f.mp3","signature":"[\"fr\",[[\"A\",\"Dans cette salle, il faut parler doucement. Il ne faut pas manger et il ne faut pas boire. Vous pouvez utiliser votre téléphone dehors, mais pas dans la salle. Le bureau ferme à dix-sept heures.\",\"female\"]]]"},"a7c5881d":{"file":"francais/lesson-21-1-a7c5881d.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, je m’appelle Julie. J’habite à Lyon depuis septembre. Mon frère habite à Paris. Ce livre est à ma sœur. Et toi, depuis quand habites-tu ici ?\",\"female\"]]]"},"f5aa5365":{"file":"francais/lesson-21-2-f5aa5365.mp3","signature":"[\"fr\",[[\"A\",\"Qui est-ce sur la photo ? C’est Marc, mon collègue. Qu’est-ce que c’est, sur la table ? C’est son passeport. Marc et ses parents partent demain. Je voyage avec eux.\",\"female\"]]]"},"c41ae9d1":{"file":"francais/lesson-22-1-c41ae9d1.mp3","signature":"[\"fr\",[[\"A\",\"Hier, j’ai pris le bus à huit heures et j’ai visité un musée. Ensuite, j’ai mangé au restaurant avec Paul. Aujourd’hui, je viens de finir mon travail. Demain, je vais rester à la maison.\",\"male\"]]]"},"0fc3cc3a":{"file":"francais/lesson-22-2-0fc3cc3a.mp3","signature":"[\"fr\",[[\"A\",\"Je m’appelle Anna. Je suis arrivée à Lyon il y a deux semaines. J’habite chez ma sœur depuis mon arrivée. Je vais partir dans trois jours. Hier, nous sommes allées au cinéma.\",\"female\"]]]"},"d2cd6798":{"file":"francais/lesson-23-1-d2cd6798.mp3","signature":"[\"fr\",[[\"A\",\"Pour ce gâteau, il faut trois œufs, deux cents grammes de farine et un peu de lait. Il ne faut pas ajouter de sucre. Mélangez avec une cuillère. Le gâteau est pour quatre personnes.\",\"female\"]]]"},"89f11be0":{"file":"francais/lesson-23-2-89f11be0.mp3","signature":"[\"fr\",[[\"A\",\"Pour la salade, prenez deux carottes, deux tomates et cent grammes de fromage. Utilisez un couteau pour couper les légumes. Ajoutez le fromage, puis mélangez avec une cuillère. Il ne faut pas ajouter trop de sel.\",\"male\"]]]"},"8591aad8":{"file":"francais/lesson-24-1-8591aad8.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, je viens du Canada. Lundi, je vais partir en France. Je dois prendre le train pour Lyon à huit heures. Le billet coûte vingt euros. Je vais rentrer vendredi, pas jeudi.\",\"female\"]]]"},"dbbc3557":{"file":"francais/lesson-24-2-dbbc3557.mp3","signature":"[\"fr\",[[\"A\",\"Nous venons d’Allemagne et nos amis viennent des États-Unis. Nous allons tous au Canada samedi. Paul doit partir à six heures. Moi, je dois partir à sept heures. Nous allons visiter Montréal. Nous allons rester trois jours.\",\"male\"]]]"},"fc463417":{"file":"francais/lesson-01-pilot-1-fc463417.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour ! Comment vous vous appelez ?\",\"female\"],[\"B\",\"Je m’appelle Luc. Je viens de Paris. J’habite à Berlin.\",\"male\"],[\"A\",\"Vous parlez allemand ?\",\"female\"],[\"B\",\"Oui, je parle allemand et un peu français. Au revoir !\",\"male\"]]]"},"49bca916":{"file":"francais-a2/lesson-01-1-49bca916.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, je m’appelle Thomas Weber. J’ai trente-six ans et je suis divorcé. J’habite à Metz depuis huit ans. Je travaille comme électricien. Je parle allemand et français. Le soir, je fais de la musique.\",\"male\"]]]"},"7264bb01":{"file":"francais-a2/lesson-01-2-7264bb01.mp3","signature":"[\"fr\",[[\"A\",\"Vous êtes étudiante ?\",\"male\"],[\"B\",\"Non, je travaille comme secrétaire dans une école.\",\"female\"],[\"A\",\"Depuis quand ?\",\"male\"],[\"B\",\"Depuis septembre. Avant, j’étais étudiante à Lyon.\",\"female\"]]]"},"b7d5f510":{"file":"francais-a2/lesson-02-1-b7d5f510.mp3","signature":"[\"fr\",[[\"A\",\"Nous cherchons un appartement de trois pièces près de l’école. Notre appartement actuel est trop petit : il a seulement deux pièces. Nous voulons un loyer de 900 euros maximum.\",\"female\"]]]"},"e815d156":{"file":"francais-a2/lesson-02-2-e815d156.mp3","signature":"[\"fr\",[[\"A\",\"Ta nouvelle chambre est grande ?\",\"male\"],[\"B\",\"Elle est aussi grande que l’ancienne, mais elle est plus claire.\",\"female\"],[\"A\",\"Et le quartier ?\",\"male\"],[\"B\",\"Il est moins animé, mais plus calme.\",\"female\"]]]"},"3494cf16":{"file":"francais-a2/lesson-03-1-3494cf16.mp3","signature":"[\"fr\",[[\"A\",\"Pour aller à la bibliothèque, vous allez tout droit jusqu’à l’église. Ensuite, vous tournez à droite. La bibliothèque est à côté de la banque, en face du jardin public.\",\"female\"]]]"},"82b9aa0f":{"file":"francais-a2/lesson-03-2-82b9aa0f.mp3","signature":"[\"fr\",[[\"A\",\"Comment tu vas au travail ?\",\"female\"],[\"B\",\"Je prends le métro, puis le bus.\",\"male\"],[\"A\",\"Tu mets combien de temps ?\",\"female\"],[\"B\",\"Quarante minutes. Le vendredi, je vais au travail à vélo.\",\"male\"]]]"},"36706e80":{"file":"francais-a2/lesson-04-1-36706e80.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, ici le cabinet du docteur Martin. Votre rendez-vous de mardi est déplacé à jeudi, à dix heures. Si ce n’est pas possible, rappelez-nous avant mercredi midi. Merci.\",\"female\"]]]"},"8c58122c":{"file":"francais-a2/lesson-04-2-8c58122c.mp3","signature":"[\"fr\",[[\"A\",\"Allô, je peux parler à Léo ?\",\"male\"],[\"B\",\"Il n’est pas là. Je lui dis de te rappeler ?\",\"female\"],[\"A\",\"Non, je lui envoie un message. Et dis à ses frères que le match est annulé.\",\"male\"],[\"B\",\"D’accord, je leur dis tout de suite.\",\"female\"]]]"},"b3099e67":{"file":"francais-a2/lesson-05-1-b3099e67.mp3","signature":"[\"fr\",[[\"A\",\"Hier, Paul a eu une journée difficile. Il s’est levé en retard et il a raté son bus. Il est arrivé au bureau à dix heures. Le soir, il est allé au sport et il s’est couché tôt.\",\"male\"]]]"},"6a2717a1":{"file":"francais-a2/lesson-05-2-6a2717a1.mp3","signature":"[\"fr\",[[\"A\",\"Tes amis sont venus samedi ?\",\"female\"],[\"B\",\"Oui, ils sont arrivés à midi et nous avons fait un barbecue.\",\"male\"],[\"A\",\"Ils sont restés longtemps ?\",\"female\"],[\"B\",\"Non, ils sont partis à quatre heures.\",\"male\"]]]"},"b29cf16f":{"file":"francais-a2/lesson-06-1-b29cf16f.mp3","signature":"[\"fr\",[[\"A\",\"L’année dernière, je suis partie au Maroc avec une amie. Nous étions dans une petite maison à Marrakech. Il faisait très chaud. Un jour, nous avons fait une excursion dans le désert. C’était magnifique.\",\"female\"]]]"},"d615a5aa":{"file":"francais-a2/lesson-06-2-d615a5aa.mp3","signature":"[\"fr\",[[\"A\",\"Vous étiez où cet hiver ?\",\"male\"],[\"B\",\"À la montagne. On faisait du ski tous les jours.\",\"male\"],[\"A\",\"Et il y avait de la neige ?\",\"male\"],[\"B\",\"Beaucoup ! Mais le dernier jour, je suis tombé et je me suis fait mal au bras.\",\"male\"]]]"},"1f280113":{"file":"francais-a2/lesson-07-1-1f280113.mp3","signature":"[\"fr\",[[\"A\",\"Ce week-end, il fera beau sur toute la France. Samedi, il fera vingt-cinq degrés à Paris. Dimanche, il y aura des nuages dans le Nord, mais il ne pleuvra pas.\",\"male\"]]]"},"7429d17e":{"file":"francais-a2/lesson-07-2-7429d17e.mp3","signature":"[\"fr\",[[\"A\",\"Tu viendras à ma fête samedi ?\",\"female\"],[\"B\",\"Oui, mais j’arriverai tard. Je travaille jusqu’à huit heures.\",\"female\"],[\"A\",\"Pas de problème. Quand tu seras là, on mangera.\",\"female\"],[\"B\",\"Super, j’apporterai le dessert !\",\"female\"]]]"},"0f20118a":{"file":"francais-a2/lesson-08-1-0f20118a.mp3","signature":"[\"fr\",[[\"A\",\"Perdu : petit chien blanc qui s’appelle Pompon. Il porte un collier rouge. On l’a vu pour la dernière fois près de la gare, samedi soir. Merci d’appeler le 06 45 12 78 90.\",\"female\"]]]"},"7aaddad9":{"file":"francais-a2/lesson-08-2-7aaddad9.mp3","signature":"[\"fr\",[[\"A\",\"Tu peux garder mon chat ce week-end ?\",\"female\"],[\"B\",\"Oui, bien sûr. Qu’est-ce qu’il mange ?\",\"male\"],[\"A\",\"Les croquettes que je laisse dans la cuisine. Deux fois par jour.\",\"female\"],[\"B\",\"D’accord. Et le poisson qui est dans le salon ?\",\"male\"]]]"},"24e3d355":{"file":"francais-a2/lesson-09-1-24e3d355.mp3","signature":"[\"fr\",[[\"A\",\"Pour la crêpe, il faut deux cent cinquante grammes de farine, quatre œufs, un demi-litre de lait et une pincée de sel. On mélange tout et on laisse reposer une heure.\",\"female\"]]]"},"0577a1c6":{"file":"francais-a2/lesson-09-2-0577a1c6.mp3","signature":"[\"fr\",[[\"A\",\"Tu manges souvent du poisson ?\",\"male\"],[\"B\",\"Oui, j’en mange deux fois par semaine.\",\"female\"],[\"A\",\"Et de la viande ?\",\"male\"],[\"B\",\"Non, je n’en mange presque jamais.\",\"female\"]]]"},"46a66fc4":{"file":"francais-a2/lesson-10-1-46a66fc4.mp3","signature":"[\"fr\",[[\"A\",\"Salut Tom, c’est Julie. Pour mon anniversaire, je t’invite à une soirée vendredi prochain, chez moi, à partir de vingt heures. Apporte quelque chose à boire si tu veux. Réponds-moi avant mercredi !\",\"female\"]]]"},"c4e8bd3b":{"file":"francais-a2/lesson-10-2-c4e8bd3b.mp3","signature":"[\"fr\",[[\"A\",\"Regarde, mon fiancé m’a offert cette bague !\",\"female\"],[\"B\",\"Oh, quelle belle bague ! Félicitations !\",\"male\"],[\"A\",\"Merci ! Nous nous marions en juin.\",\"female\"],[\"B\",\"Quelle bonne nouvelle ! Il faut fêter ça.\",\"male\"]]]"},"e0c5d738":{"file":"francais-a2/lesson-11-1-e0c5d738.mp3","signature":"[\"fr\",[[\"A\",\"Chers clients, notre magasin fermera dans quinze minutes. Merci de vous diriger vers les caisses. La caisse numéro deux est réservée aux petits achats, moins de dix articles.\",\"male\"]]]"},"f93570b7":{"file":"francais-a2/lesson-11-2-f93570b7.mp3","signature":"[\"fr\",[[\"A\",\"Les fraises sont à combien ?\",\"female\"],[\"B\",\"Quatre euros la barquette, mais deux barquettes pour sept euros.\",\"male\"],[\"A\",\"Je n’en prends qu’une.\",\"female\"],[\"B\",\"Alors ça fait quatre euros.\",\"male\"]]]"},"2d1abeeb":{"file":"francais-a2/lesson-12-1-2d1abeeb.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, c’est Nicolas. Je suis désolé, je serai en retard ce soir. Mon train a une heure de retard. Commencez à manger sans moi. J’arriverai vers neuf heures.\",\"male\"]]]"},"6613dc29":{"file":"francais-a2/lesson-12-2-6613dc29.mp3","signature":"[\"fr\",[[\"A\",\"Excuse-moi, je ne pourrai pas venir au match samedi.\",\"female\"],[\"B\",\"Ah, dommage ! Pourquoi ?\",\"male\"],[\"A\",\"Parce que ma grand-mère fête ses quatre-vingts ans.\",\"female\"],[\"B\",\"Ce n’est pas grave. On ira au prochain match ensemble.\",\"male\"]]]"},"db02560f":{"file":"francais-a2/lesson-13-1-db02560f.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour, ici le cabinet dentaire du docteur Simon. Nous sommes ouverts du lundi au vendredi, de huit heures à dix-huit heures. Le samedi, le cabinet est fermé. En cas d’urgence le week-end, appelez le 15.\",\"female\"]]]"},"c9b029a1":{"file":"francais-a2/lesson-13-2-c9b029a1.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour docteur. J’ai très mal à la tête depuis lundi.\",\"female\"],[\"B\",\"Vous avez de la fièvre ?\",\"male\"],[\"A\",\"Non, mais je dors mal et je suis très fatiguée.\",\"female\"],[\"B\",\"Je vous donne un médicament. Prenez-le le soir, pendant une semaine.\",\"male\"]]]"},"c206fda2":{"file":"francais-a2/lesson-14-1-c206fda2.mp3","signature":"[\"fr\",[[\"A\",\"Votre attention, s’il vous plaît. Le train Intercités pour Clermont-Ferrand, départ prévu à 11 h 20, partira voie 2 au lieu de voie 6. Nous vous remercions de votre compréhension.\",\"female\"]]]"},"836d92de":{"file":"francais-a2/lesson-14-2-836d92de.mp3","signature":"[\"fr\",[[\"A\",\"Pardon, le train pour Lille est à l’heure ?\",\"male\"],[\"B\",\"Non, il a dix minutes de retard. Il partira à 9 h 25.\",\"female\"],[\"A\",\"Et il part de quelle voie ?\",\"male\"],[\"B\",\"Voie 8. Vous avez votre billet ?\",\"female\"]]]"},"e41516b6":{"file":"francais-a2/lesson-15-1-e41516b6.mp3","signature":"[\"fr\",[[\"A\",\"Information trafic : sur la nationale 7, la route est fermée entre Valence et Montélimar en raison de travaux, jusqu’à vendredi. Une déviation est en place par Crest.\",\"male\"]]]"},"fcf6d321":{"file":"francais-a2/lesson-15-2-fcf6d321.mp3","signature":"[\"fr\",[[\"A\",\"Mesdames et messieurs, le propriétaire de la voiture noire garée devant la sortie de secours est prié de la déplacer.\",\"female\"],[\"B\",\"C’est notre voiture ?\",\"male\"],[\"A\",\"Il s’agit d’une Citroën noire, immatriculée 72 BL 16.\",\"female\"],[\"B\",\"Non, la nôtre est une Renault. Ce n’est pas pour nous.\",\"male\"]]]"},"6a1d23e2":{"file":"francais-a2/lesson-16-1-6a1d23e2.mp3","signature":"[\"fr\",[[\"A\",\"Météo du week-end : samedi, il fera beau sur toute la France avec vingt-cinq degrés à Lyon. Dimanche, des nuages arriveront par l’ouest et il pleuvra en soirée à Paris.\",\"female\"]]]"},"4ede44d6":{"file":"francais-a2/lesson-16-2-4ede44d6.mp3","signature":"[\"fr\",[[\"A\",\"Il a fait beau pendant tes vacances ?\",\"male\"],[\"B\",\"La première semaine, oui. Mais ensuite, il a plu tous les jours.\",\"female\"],[\"A\",\"Et maintenant, il fait comment chez toi ?\",\"male\"],[\"B\",\"Il fait gris, mais demain il fera beau.\",\"female\"]]]"},"3f8d2051":{"file":"francais-a2/lesson-17-1-3f8d2051.mp3","signature":"[\"fr\",[[\"A\",\"Moi, j’ai acheté mon premier portable il y a seulement un mois. Avant, je ne voulais pas. Mais maintenant, je trouve ça pratique pour appeler mes petits-enfants.\",\"female\"]]]"},"1f39b68a":{"file":"francais-a2/lesson-17-2-1f39b68a.mp3","signature":"[\"fr\",[[\"A\",\"Tu ne trouves pas que les gens regardent trop leur portable ?\",\"male\"],[\"B\",\"Si, je suis d’accord. Au restaurant, plus personne ne parle.\",\"female\"],[\"A\",\"Moi, je ne prends plus mon portable quand je sors.\",\"male\"],[\"B\",\"Bonne idée, je vais essayer.\",\"female\"]]]"},"3cd059ab":{"file":"francais-a2/lesson-18-1-3cd059ab.mp3","signature":"[\"fr\",[[\"A\",\"Selon l’Institut national de la statistique, la ville de Bordeaux compte maintenant deux cent soixante mille habitants. C’est cinq pour cent de plus qu’il y a dix ans.\",\"male\"]]]"},"e952a04d":{"file":"francais-a2/lesson-18-2-e952a04d.mp3","signature":"[\"fr\",[[\"A\",\"Tu savais que la moitié des Français ont un chat ou un chien ?\",\"female\"],[\"B\",\"La moitié ? C’est beaucoup !\",\"male\"],[\"A\",\"Oui, et un sur quatre a un chat.\",\"female\"],[\"B\",\"Moi, je fais partie des autres : je n’ai qu’un poisson !\",\"male\"]]]"},"8fdcc10b":{"file":"francais-a2/lesson-19-1-8fdcc10b.mp3","signature":"[\"fr\",[[\"A\",\"Bienvenue à Annecy ! Le lac d’Annecy est l’un des lacs les plus propres d’Europe. On peut s’y baigner de juin à septembre. Pour la meilleure vue, montez au château.\",\"female\"]]]"},"d7192aa9":{"file":"francais-a2/lesson-19-2-d7192aa9.mp3","signature":"[\"fr\",[[\"A\",\"Tu me conseilles quoi à Lyon ?\",\"male\"],[\"B\",\"Il faut aller dans le Vieux-Lyon, c’est le quartier le plus ancien.\",\"female\"],[\"A\",\"Et pour manger ?\",\"male\"],[\"B\",\"Les bouchons ! Ce sont les restaurants les plus typiques.\",\"female\"]]]"},"20416c15":{"file":"francais-a2/lesson-20-1-20416c15.mp3","signature":"[\"fr\",[[\"A\",\"Salut Max ! J’ai une idée pour dimanche : on pourrait faire une randonnée en forêt. Après, on pourrait manger dans le petit restaurant du village. Je préfère partir tôt, vers huit heures, parce qu’il fera chaud l’après-midi.\",\"female\"]]]"},"733e25f4":{"file":"francais-a2/lesson-20-2-733e25f4.mp3","signature":"[\"fr\",[[\"A\",\"Ça te dit d’aller au cinéma ce soir ?\",\"male\"],[\"B\",\"Non, je préfère rester à la maison. Je suis fatiguée.\",\"female\"],[\"A\",\"Alors demain soir ?\",\"male\"],[\"B\",\"Demain, oui ! À vingt heures trente, d’accord ?\",\"female\"]]]"},"c8e9d9ac":{"file":"francais-a2/lesson-21-1-c8e9d9ac.mp3","signature":"[\"fr\",[[\"A\",\"Pour vous inscrire au cours du soir, envoyez-nous le formulaire avant le quinze septembre. Les cours commencent le premier octobre, le mardi et le jeudi, de dix-neuf heures à vingt et une heures.\",\"female\"]]]"},"f1093ae4":{"file":"francais-a2/lesson-21-2-f1093ae4.mp3","signature":"[\"fr\",[[\"A\",\"Comment tu as appris l’espagnol si vite ?\",\"female\"],[\"B\",\"J’ai regardé beaucoup de séries en version originale.\",\"male\"],[\"A\",\"Avec des sous-titres ?\",\"female\"],[\"B\",\"Au début, oui. Et j’ai parlé avec des collègues tous les jours. N’aie pas peur, essaie !\",\"male\"]]]"},"e14f9643":{"file":"francais-a2/lesson-22-1-e14f9643.mp3","signature":"[\"fr\",[[\"A\",\"Chère Laura, merci pour ta lettre ! Nous avons trouvé une école près de la Bastille : le cours intensif coûte six cents euros pour quatre semaines. Nos voisins peuvent te loger. À bientôt ! Sophie\",\"female\"]]]"},"bf5347da":{"file":"francais-a2/lesson-22-2-bf5347da.mp3","signature":"[\"fr\",[[\"A\",\"Tu pourrais relire ma lettre pour l’examen ?\",\"male\"],[\"B\",\"Bien sûr. Tu as mis une formule au début ?\",\"female\"],[\"A\",\"Oui, « Chers amis ». Mais j’ai oublié la fin.\",\"male\"],[\"B\",\"Alors ajoute « Je vous embrasse » et ton prénom.\",\"female\"]]]"},"2f9993b2":{"file":"francais-a2/lesson-23-1-2f9993b2.mp3","signature":"[\"fr\",[[\"A\",\"Mon quartier est très pratique. La boulangerie est en face de chez moi et le supermarché est à côté de l’école. Le parc ? J’y cours tous les matins. Je ne prends jamais la voiture.\",\"male\"]]]"},"f0e77bd8":{"file":"francais-a2/lesson-23-2-f0e77bd8.mp3","signature":"[\"fr\",[[\"A\",\"Tu as vu mes lunettes ?\",\"female\"],[\"B\",\"Oui, je les ai vues sur la table, à côté du téléphone.\",\"male\"],[\"A\",\"Et ma veste ?\",\"female\"],[\"B\",\"Elle est contre la porte. Tu la mets toujours là !\",\"male\"]]]"},"2338403e":{"file":"francais-a2/lesson-24-1-2338403e.mp3","signature":"[\"fr\",[[\"A\",\"Bonjour. Nous allons commencer la partie trois. Vous et votre partenaire voulez passer dimanche ensemble. Faites des propositions, donnez vos raisons et mettez-vous d’accord sur deux activités.\",\"female\"]]]"},"75abbdc1":{"file":"francais-a2/lesson-24-2-75abbdc1.mp3","signature":"[\"fr\",[[\"A\",\"Tu as eu combien de points ?\",\"male\"],[\"B\",\"Quatre-vingt-trois ! Et toi ?\",\"female\"],[\"A\",\"Soixante-quatre. C’est juste, mais j’ai réussi !\",\"male\"],[\"B\",\"Bravo ! Moi, j’ai « bien ».\",\"female\"]]]"},"488c3880":{"file":"deutsch/lesson-01-1-488c3880.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag! Ich heiße Marie. Wie heißen Sie?\",\"female\"],[\"B\",\"Guten Tag! Ich heiße Marc.\",\"male\"],[\"A\",\"Woher kommen Sie?\",\"female\"],[\"B\",\"Ich komme aus Kanada. Und Sie?\",\"male\"],[\"A\",\"Ich komme aus Frankreich. Ich wohne in Bonn. Wo wohnen Sie?\",\"female\"],[\"B\",\"Ich wohne in Berlin. Ich spreche Deutsch und Französisch.\",\"male\"],[\"A\",\"Ich spreche Französisch und ein bisschen Deutsch. Auf Wiedersehen!\",\"female\"]]]"},"d8b68bb3":{"file":"deutsch/lesson-01-2-d8b68bb3.mp3","signature":"[\"de\",[[\"A\",\"Hallo! Ich heiße Anna. Ich komme aus Deutschland. Ich wohne in Halifax. Ich bin Studentin. Ich spreche Deutsch und ein bisschen Französisch. Mein Hobby ist Volleyball. Auf Wiedersehen!\",\"female\"]]]"},"b0651f3e":{"file":"deutsch/lesson-02-1-b0651f3e.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag! Wie ist Ihr Familienname?\",\"female\"],[\"B\",\"Mein Familienname ist Müller.\",\"male\"],[\"A\",\"Können Sie das bitte buchstabieren?\",\"female\"],[\"B\",\"Ja. M, Ü, L, L, E, R. Müller, mit Umlaut und Doppel-l.\",\"male\"],[\"A\",\"Danke. Und Ihr Vorname?\",\"female\"],[\"B\",\"Paul. P, A, U, L.\",\"male\"],[\"A\",\"Können Sie den Vornamen bitte wiederholen?\",\"female\"],[\"B\",\"Paul. Ohne Bindestrich.\",\"male\"]]]"},"2aabb596":{"file":"deutsch/lesson-02-2-2aabb596.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag! Mein Vorname ist Anna-Lena. Anna mit Doppel-n und dann ein Bindestrich. Lena schreibt man L, E, N, A. Mein Familienname ist Weber. W, E, B, E, R. Ohne Umlaut. Vielen Dank!\",\"female\"]]]"},"88ebc0ba":{"file":"deutsch/lesson-03-1-88ebc0ba.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag! Wie heißen Sie?\",\"female\"],[\"B\",\"Ich heiße Paul Weber.\",\"male\"],[\"A\",\"Wo wohnen Sie?\",\"female\"],[\"B\",\"In Berlin. Meine Postleitzahl ist 10115.\",\"male\"],[\"A\",\"Wie ist Ihre Telefonnummer?\",\"female\"],[\"B\",\"030 21 34 56.\",\"male\"]]]"},"b29359d4":{"file":"deutsch/lesson-03-2-b29359d4.mp3","signature":"[\"de\",[[\"A\",\"Hallo, hier ist Lea. Ich bin einundzwanzig Jahre alt und wohne in Bonn. Meine Telefonnummer ist 0228 45 67 89.\",\"female\"]]]"},"3805ebc7":{"file":"deutsch/lesson-04-1-3805ebc7.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag! Ich brauche einen Termin.\",\"female\"],[\"B\",\"Am Montag um zehn Uhr?\",\"male\"],[\"A\",\"Am Montag kann ich nicht. Geht es am Dienstag?\",\"female\"],[\"B\",\"Ja, am Dienstag um Viertel nach vier.\",\"male\"],[\"A\",\"Also um sechzehn Uhr fünfzehn?\",\"female\"],[\"B\",\"Genau. Der Termin ist im April.\",\"male\"],[\"A\",\"Danke. Am Dienstag um sechzehn Uhr fünfzehn. Auf Wiedersehen!\",\"female\"]]]"},"285a77a1":{"file":"deutsch/lesson-05-1-285a77a1.mp3","signature":"[\"de\",[[\"A\",\"Das ist meine Familie.\",\"female\"],[\"B\",\"Wer ist das?\",\"male\"],[\"A\",\"Das ist mein Vater. Er heißt Thomas und wohnt in Bonn.\",\"female\"],[\"B\",\"Und das ist deine Mutter?\",\"male\"],[\"A\",\"Ja. Sie heißt Anna. Mein Bruder heißt Paul. Er wohnt in Berlin.\",\"female\"],[\"B\",\"Hast du eine Schwester?\",\"male\"],[\"A\",\"Ja, sie heißt Lea. Sie wohnt auch in Berlin.\",\"female\"]]]"},"1d883b12":{"file":"deutsch/lesson-05-2-1d883b12.mp3","signature":"[\"de\",[[\"A\",\"Hallo, ich heiße Marc Weber. Ich bin verheiratet. Mein Geburtsdatum ist der dritte April neunzehnhundertneunzig. Ich wohne mit meiner Frau in Bonn. Meine Schwester wohnt in Berlin.\",\"male\"]]]"},"9b97aff3":{"file":"deutsch/lesson-06-1-9b97aff3.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag! Was möchten Sie?\",\"female\"],[\"B\",\"Ich hätte gern eine Suppe ohne Fleisch und einen Kaffee.\",\"male\"],[\"A\",\"Den Kaffee mit Milch?\",\"female\"],[\"B\",\"Nein, ohne Milch. Aber mit Zucker, bitte.\",\"male\"],[\"A\",\"Und für Ihre Freundin?\",\"female\"],[\"B\",\"Ein Wasser ohne Eis und einen Salat.\",\"male\"],[\"A\",\"Gern. Zusammen kostet das neunzehn Euro.\",\"female\"],[\"B\",\"Die Rechnung, bitte.\",\"male\"]]]"},"21712ff8":{"file":"deutsch/lesson-06-2-21712ff8.mp3","signature":"[\"de\",[[\"A\",\"Hallo Nora! Ich bin im Café. Ich nehme einen Kaffee ohne Zucker, aber mit Milch. Für dich bestelle ich eine Suppe ohne Fleisch. Das kostet zusammen dreizehn Euro. Ich warte hier auf dich.\",\"female\"]]]"},"74b149c1":{"file":"deutsch/lesson-07-1-74b149c1.mp3","signature":"[\"de\",[[\"A\",\"Kann ich Ihnen helfen?\",\"female\"],[\"B\",\"Ich suche eine Jacke. Was kostet diese rote Jacke?\",\"male\"],[\"A\",\"Dreißig Euro.\",\"female\"],[\"B\",\"Das ist zu teuer. Und die blaue?\",\"male\"],[\"A\",\"Zwanzig Euro. Hier ist Größe S.\",\"female\"],[\"B\",\"Die ist zu klein. Haben Sie Größe M?\",\"male\"],[\"A\",\"Ja.\",\"female\"],[\"B\",\"Die passt. Ich nehme die blaue Jacke in Größe M.\",\"male\"]]]"},"6c9e7eaf":{"file":"deutsch/lesson-07-2-6c9e7eaf.mp3","signature":"[\"de\",[[\"A\",\"Hallo! Hier ist eine Hose für neunzehn Euro. Leider ist sie zu lang. Die Jacke kostet dreißig Euro, das ist mir zu teuer. Ich kaufe nur ein T-Shirt für dreizehn Euro.\",\"female\"]]]"},"e992dd3a":{"file":"deutsch/lesson-08-1-e992dd3a.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag! Ich suche eine Wohnung.\",\"female\"],[\"B\",\"Wir haben eine Wohnung mit zwei Zimmern.\",\"male\"],[\"A\",\"Hat sie einen Balkon?\",\"female\"],[\"B\",\"Ja. Die Miete ist sechshundert Euro.\",\"male\"],[\"A\",\"Kann ich die Wohnung am Montag sehen?\",\"female\"],[\"B\",\"Am Montag geht es nicht. Am Dienstag um zehn Uhr?\",\"male\"],[\"A\",\"Ja, gern. Vielen Dank!\",\"female\"]]]"},"f823e158":{"file":"deutsch/lesson-08-2-f823e158.mp3","signature":"[\"de\",[[\"A\",\"Hallo Nora! Ich habe ein Zimmer in Berlin. Es kostet dreihundert Euro. Es gibt eine Küche und ein Bad, aber keinen Balkon. Die Besichtigung ist am Freitag um elf Uhr. Kommst du mit?\",\"female\"]]]"},"9398acdc":{"file":"deutsch/lesson-09-1-9398acdc.mp3","signature":"[\"de\",[[\"A\",\"Entschuldigung, wie komme ich zum Bahnhof?\",\"female\"],[\"B\",\"Gehen Sie geradeaus und dann nach rechts. Dort ist die Haltestelle.\",\"male\"],[\"A\",\"Fährt die Linie drei zum Bahnhof?\",\"female\"],[\"B\",\"Nein, die Linie drei fährt zum Markt. Nehmen Sie die Linie acht.\",\"male\"],[\"A\",\"Wann fährt der Bus?\",\"female\"],[\"B\",\"Um Viertel nach zehn.\",\"male\"],[\"A\",\"Danke. Muss ich hier eine Fahrkarte kaufen?\",\"female\"],[\"B\",\"Ja, am Automaten.\",\"male\"]]]"},"fcd9dc52":{"file":"deutsch/lesson-09-2-fcd9dc52.mp3","signature":"[\"de\",[[\"A\",\"Hallo Nora, hier ist Paul. Ich bin an der Schule. Die Linie dreizehn fährt hier ab. Du brauchst aber die Linie achtzehn zum Krankenhaus. Die Haltestelle ist links neben der Apotheke. Geh nicht nach rechts!\",\"male\"]]]"},"6cf90550":{"file":"deutsch/lesson-10-1-6cf90550.mp3","signature":"[\"de\",[[\"A\",\"Guten Morgen, hier ist Nora. Ich komme heute später.\",\"female\"],[\"B\",\"Guten Morgen. Wann kommst du?\",\"male\"],[\"A\",\"Um neun Uhr. Mein Bus kommt nicht.\",\"female\"],[\"B\",\"Gut. Du arbeitest heute im Büro, nicht im Supermarkt.\",\"male\"],[\"A\",\"Ja. Arbeitet Paul auch im Büro?\",\"female\"],[\"B\",\"Nein, Paul arbeitet heute in der Schule.\",\"male\"],[\"A\",\"Danke. Bis neun Uhr!\",\"female\"]]]"},"b55f9a85":{"file":"deutsch/lesson-10-2-b55f9a85.mp3","signature":"[\"de\",[[\"A\",\"Guten Morgen! Hier ist Paul. Ich arbeite im Krankenhaus. Am Montag beginne ich um acht Uhr. Am Freitag arbeite ich bis fünf Uhr. Morgen komme ich später, um neun Uhr. Vielen Dank!\",\"male\"]]]"},"365a4a30":{"file":"deutsch/lesson-11-1-365a4a30.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag! Wann ist der Deutschkurs?\",\"female\"],[\"B\",\"Am Montag und Mittwoch von neun bis elf Uhr.\",\"male\"],[\"A\",\"Also am Vormittag. Gibt es auch einen Abendkurs?\",\"female\"],[\"B\",\"Ja, am Dienstag um neunzehn Uhr.\",\"male\"],[\"A\",\"Ich möchte den Kurs am Vormittag. Was brauche ich?\",\"female\"],[\"B\",\"Ein Buch und ein Wörterbuch.\",\"male\"],[\"A\",\"Gibt es Hausaufgaben?\",\"female\"],[\"B\",\"Ja, für Mittwoch lesen Sie einen Text.\",\"male\"]]]"},"3bd0b043":{"file":"deutsch/lesson-11-2-3bd0b043.mp3","signature":"[\"de\",[[\"A\",\"Hallo Nora! Ich lerne heute am Nachmittag Deutsch. Ich mache zuerst meine Hausaufgaben. Dann lese ich ein Buch. Mein Wörterbuch ist in der Schule. Kannst du dein Wörterbuch mitbringen? Am Abend habe ich keine Zeit.\",\"female\"]]]"},"f3cff7b6":{"file":"deutsch/lesson-12-1-f3cff7b6.mp3","signature":"[\"de\",[[\"A\",\"Hallo Paul! Spielst du am Samstag Fußball?\",\"female\"],[\"B\",\"Nein, am Samstag spiele ich Tennis. Fußball spiele ich am Sonntag.\",\"male\"],[\"A\",\"Kann ich am Sonntag mitspielen?\",\"female\"],[\"B\",\"Ja, wir treffen uns um zehn Uhr im Park.\",\"male\"],[\"A\",\"Ich habe erst um elf Uhr Zeit.\",\"female\"],[\"B\",\"Gut, dann beginnen wir um elf Uhr.\",\"male\"],[\"A\",\"Super. Bis Sonntag!\",\"female\"]]]"},"3c66079e":{"file":"deutsch/lesson-12-2-3c66079e.mp3","signature":"[\"de\",[[\"A\",\"Hallo Nora! Am Freitag spiele ich Volleyball. Am Samstag arbeite ich. Am Sonntag habe ich Zeit und spiele Basketball. Kommst du am Sonntag um drei Uhr in den Park? Bring bitte Wasser mit.\",\"male\"]]]"},"1e65d124":{"file":"deutsch/lesson-13-1-1e65d124.mp3","signature":"[\"de\",[[\"A\",\"Hotel Adler, guten Tag!\",\"female\"],[\"B\",\"Guten Tag! Ich möchte ein Doppelzimmer für zwei Nächte reservieren.\",\"male\"],[\"A\",\"Gern. Mit Frühstück?\",\"female\"],[\"B\",\"Ja, bitte. Was kostet das Zimmer?\",\"male\"],[\"A\",\"Achtzig Euro pro Nacht, mit Frühstück.\",\"female\"],[\"B\",\"Wir kommen am Freitag. Unser Zug fährt um neun Uhr ab.\",\"male\"],[\"A\",\"Gut. Das Zimmer ist ab zwei Uhr frei.\",\"female\"]]]"},"971ceefc":{"file":"deutsch/lesson-13-2-971ceefc.mp3","signature":"[\"de\",[[\"A\",\"Hallo Nora! Unser Zug fährt morgen früh um acht Uhr ab. Wir treffen uns um Viertel vor acht am Bahnhof. Ich möchte ein Doppelzimmer im Hotel Adler, ohne Frühstück. Bitte bring deine Fahrkarte mit.\",\"female\"]]]"},"edf31a40":{"file":"deutsch/lesson-14-1-edf31a40.mp3","signature":"[\"de\",[[\"A\",\"Arztpraxis, guten Tag!\",\"female\"],[\"B\",\"Guten Tag! Ich habe Husten und Halsschmerzen. Ich brauche einen Termin.\",\"male\"],[\"A\",\"Haben Sie auch Fieber?\",\"female\"],[\"B\",\"Nein, kein Fieber.\",\"male\"],[\"A\",\"Heute um vier Uhr ist ein Termin frei.\",\"female\"],[\"B\",\"Heute kann ich nicht. Geht es morgen?\",\"male\"],[\"A\",\"Morgen um zehn Uhr.\",\"female\"],[\"B\",\"Ja, vielen Dank.\",\"male\"]]]"},"6b7628cf":{"file":"deutsch/lesson-14-2-6b7628cf.mp3","signature":"[\"de\",[[\"A\",\"Guten Morgen, hier ist Anna. Ich kann heute nicht zur Arbeit kommen. Ich habe Fieber und Kopfschmerzen. Morgen habe ich um neun Uhr einen Termin beim Arzt. Bitte informieren Sie Herrn Weber. Vielen Dank!\",\"female\"]]]"},"e10ac1ac":{"file":"deutsch/lesson-15-1-e10ac1ac.mp3","signature":"[\"de\",[[\"A\",\"Hallo Paul! Ich feiere am Samstag Geburtstag. Kommst du?\",\"female\"],[\"B\",\"Gern! Um wie viel Uhr?\",\"male\"],[\"A\",\"Um achtzehn Uhr bei mir zu Hause.\",\"female\"],[\"B\",\"Soll ich einen Salat mitbringen?\",\"male\"],[\"A\",\"Lea bringt schon einen Salat. Bring bitte einen Kuchen mit.\",\"female\"],[\"B\",\"Gern. Brauchst du auch Wasser?\",\"male\"],[\"A\",\"Nein, Wasser und Brot habe ich. Bis Samstag!\",\"female\"]]]"},"0d965346":{"file":"deutsch/lesson-15-2-0d965346.mp3","signature":"[\"de\",[[\"A\",\"Hallo Nora, hier ist Marc. Danke für die Einladung. Am Samstag kann ich leider nicht kommen. Am Sonntag habe ich Zeit. Ich bringe dann einen Salat und Wasser mit. Können wir uns am Sonntag treffen?\",\"male\"]]]"},"b3149955":{"file":"deutsch/lesson-16-1-b3149955.mp3","signature":"[\"de\",[[\"A\",\"Entschuldigung, ist das Museum heute geöffnet?\",\"female\"],[\"B\",\"Ja, von zehn bis sechs Uhr.\",\"male\"],[\"A\",\"Darf ich fotografieren?\",\"female\"],[\"B\",\"Nein, Fotografieren ist hier verboten. Essen ist nur im Café erlaubt.\",\"male\"],[\"A\",\"Wo ist das Café?\",\"female\"],[\"B\",\"Links am Eingang. Es schließt schon um siebzehn Uhr.\",\"male\"],[\"A\",\"Vielen Dank!\",\"female\"]]]"},"c3f687e8":{"file":"deutsch/lesson-16-2-c3f687e8.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag! Unser Geschäft ist heute geschlossen. Morgen sind wir von neun bis achtzehn Uhr geöffnet. Bitte parken Sie nicht vor dem Eingang. Der Parkplatz ist hinter dem Haus. Vielen Dank!\",\"female\"]]]"},"644ec937":{"file":"deutsch/lesson-17-1-644ec937.mp3","signature":"[\"de\",[[\"A\",\"Entschuldigung, können Sie mir bitte einen Stift geben?\",\"female\"],[\"B\",\"Ja, natürlich. Hier bitte.\",\"male\"],[\"A\",\"Vielen Dank. Und können Sie mir bitte das Buch geben?\",\"female\"],[\"B\",\"Einen Moment, bitte. Ich brauche es noch.\",\"male\"],[\"A\",\"Kein Problem. Kann ich das Glas nehmen?\",\"female\"],[\"B\",\"Leider nicht. Das ist mein Glas. Hier ist ein anderes.\",\"male\"],[\"A\",\"Danke, das ist sehr nett.\",\"female\"]]]"},"975e19d7":{"file":"deutsch/lesson-17-2-975e19d7.mp3","signature":"[\"de\",[[\"A\",\"Hallo Nora! Kannst du mir bitte dein Buch geben? Mein Buch ist in der Schule. Ich brauche auch einen Stift. Die Tasche kannst du zu Hause lassen. Vielen Dank für deine Hilfe!\",\"female\"]]]"},"8fb98502":{"file":"deutsch/lesson-18-1-8fb98502.mp3","signature":"[\"de\",[[\"A\",\"Was machen wir zuerst?\",\"female\"],[\"B\",\"Zuerst lesen wir die Aufgabe. Dann hören wir den Text.\",\"male\"],[\"A\",\"Schreiben wir sofort einen langen Text?\",\"female\"],[\"B\",\"Nein. Wir kreuzen die richtige Antwort an.\",\"male\"],[\"A\",\"Und danach?\",\"female\"],[\"B\",\"Danach schreiben wir eine kurze Nachricht. Zum Schluss prüfen wir den Text.\",\"male\"],[\"A\",\"Gut. Ich lese zuerst die Aufgabe.\",\"female\"]]]"},"f9cdaeab":{"file":"deutsch/lesson-18-2-f9cdaeab.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag! Lesen Sie bitte zuerst die Fragen. Hören Sie dann den Dialog. Kreuzen Sie die Antworten an. Schreiben Sie danach eine kurze Nachricht. Prüfen Sie am Ende Ihren Text. Sie haben eine Frage? Fragen Sie bitte.\",\"female\"]]]"},"969deeb5":{"file":"deutsch/lesson-19-1-969deeb5.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag! Was fehlt Ihnen?\",\"female\"],[\"B\",\"Mein Bauch tut weh.\",\"male\"],[\"A\",\"Seit wann?\",\"female\"],[\"B\",\"Seit gestern. Meine Beine tun auch weh, aber mein Kopf ist in Ordnung.\",\"male\"],[\"A\",\"Haben Sie schon einen Termin beim Arzt?\",\"female\"],[\"B\",\"Nein. Ich brauche einen Termin für heute.\",\"male\"],[\"A\",\"Heute um fünfzehn Uhr geht es.\",\"female\"],[\"B\",\"Vielen Dank.\",\"male\"]]]"},"39dac38b":{"file":"deutsch/lesson-19-2-39dac38b.mp3","signature":"[\"de\",[[\"A\",\"Hallo Nora! Mein Hals tut weh. Tee habe ich zu Hause. Ich gehe heute zur Apotheke und kaufe Tabletten. Einen Arzt brauche ich im Moment nicht. Kannst du mich um vier Uhr an der Apotheke treffen?\",\"female\"]]]"},"3ae64ec5":{"file":"deutsch/lesson-20-1-3ae64ec5.mp3","signature":"[\"de\",[[\"A\",\"Wie ist das Wetter heute?\",\"female\"],[\"B\",\"Es ist kalt und windig. Am Nachmittag regnet es.\",\"male\"],[\"A\",\"Dann brauche ich einen Mantel.\",\"female\"],[\"B\",\"Ja. Nimm auch einen Regenschirm mit.\",\"male\"],[\"A\",\"Ist es morgen auch kalt?\",\"female\"],[\"B\",\"Nein, morgen ist es warm und sonnig.\",\"male\"],[\"A\",\"Gut. Dann brauche ich morgen keinen Mantel.\",\"female\"]]]"},"eee3773c":{"file":"deutsch/lesson-20-2-eee3773c.mp3","signature":"[\"de\",[[\"A\",\"Hallo Nora! Ich bin im Geschäft. Ich brauche eine Jacke für das kalte Wetter. Die rote Jacke ist zu klein. Die blaue Jacke passt und kostet dreißig Euro. Einen Regenschirm habe ich schon.\",\"female\"]]]"},"f098d4fe":{"file":"deutsch/lesson-21-1-f098d4fe.mp3","signature":"[\"de\",[[\"A\",\"Hallo Paul! Gehen wir am Freitag ins Kino?\",\"female\"],[\"B\",\"Ich möchte lieber ins Konzert.\",\"male\"],[\"A\",\"Wann beginnt es?\",\"female\"],[\"B\",\"Um neunzehn Uhr.\",\"male\"],[\"A\",\"Gut. Wo treffen wir uns?\",\"female\"],[\"B\",\"Vor dem Bahnhof um achtzehn Uhr dreißig.\",\"male\"],[\"A\",\"Kaufst du die Karten?\",\"female\"],[\"B\",\"Ja, zwei Karten für uns.\",\"male\"]]]"},"a614581d":{"file":"deutsch/lesson-21-2-a614581d.mp3","signature":"[\"de\",[[\"A\",\"Hallo Nora! Das Museum ist am Sonntag bis achtzehn Uhr geöffnet. Danach können wir ins Kino gehen. Der Film beginnt um zwanzig Uhr. Ich habe schon zwei Karten. Kommst du mit?\",\"female\"]]]"},"8da3ffe5":{"file":"deutsch/lesson-22-1-8da3ffe5.mp3","signature":"[\"de\",[[\"A\",\"Hallo Paul, hier ist Nora. Kannst du mich heute zurückrufen?\",\"female\"],[\"B\",\"Heute arbeite ich bis sechs Uhr. Geht es morgen?\",\"male\"],[\"A\",\"Ja, morgen am Vormittag.\",\"female\"],[\"B\",\"Gut. Schickst du mir deine Adresse?\",\"male\"],[\"A\",\"Ja, ich schicke dir eine E-Mail. Das Foto schicke ich dir später.\",\"female\"],[\"B\",\"Danke. Dann rufe ich dich morgen um zehn Uhr an.\",\"male\"]]]"},"b6d615cb":{"file":"deutsch/lesson-22-2-b6d615cb.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag, hier ist Herr Weber. Bitte rufen Sie mich am Dienstag zurück. Meine Telefonnummer ist 030 45 67 89. Ich brauche Ihre Adresse für das Formular. Sie können mir auch eine E-Mail schicken. Vielen Dank!\",\"male\"]]]"},"6d30b567":{"file":"deutsch/lesson-23-1-6d30b567.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag! Was brauchen Sie?\",\"female\"],[\"B\",\"Eine Briefmarke und einen Umschlag, bitte.\",\"male\"],[\"A\",\"Für Deutschland oder für Kanada?\",\"female\"],[\"B\",\"Für Kanada. Ich möchte einen Brief schicken.\",\"male\"],[\"A\",\"Gern. Das kostet zusammen vier Euro.\",\"female\"],[\"B\",\"Kann ich hier auch ein Formular bekommen?\",\"male\"],[\"A\",\"Ja. Für das Formular brauche ich Ihren Ausweis.\",\"female\"],[\"B\",\"Hier bitte.\",\"male\"]]]"},"d1151dcc":{"file":"deutsch/lesson-23-2-d1151dcc.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag, Frau Weber. In Ihrem Formular fehlt das Geburtsdatum. Der Familienname, der Vorname und die Adresse sind schon da. Bitte kommen Sie am Mittwoch um elf Uhr und bringen Sie Ihren Ausweis mit. Vielen Dank!\",\"female\"]]]"},"634b0e21":{"file":"deutsch/lesson-24-1-634b0e21.mp3","signature":"[\"de\",[[\"A\",\"Guten Tag! Wie heißen Sie?\",\"female\"],[\"B\",\"Ich heiße Paul Weber. Ich komme aus Kanada und wohne in Bonn. Wann ist unser Treffen?\",\"male\"],[\"A\",\"Am Samstag um achtzehn Uhr.\",\"female\"],[\"B\",\"Am Samstag kann ich erst um neunzehn Uhr.\",\"male\"],[\"A\",\"Gut, dann treffen wir uns um neunzehn Uhr vor dem Bahnhof.\",\"female\"]]]"},"d28f16de":{"file":"deutsch/lesson-24-2-d28f16de.mp3","signature":"[\"de\",[[\"A\",\"Hallo Nora! Vielen Dank für deine Nachricht. Am Freitag arbeite ich, aber am Sonntag habe ich Zeit. Komm bitte um achtzehn Uhr zu mir. Bring einen Salat mit. Einen Kuchen und Wasser habe ich schon. Bis Sonntag!\",\"female\"]]]"},"7dd587f1":{"file":"englisch/lesson-01-1-7dd587f1.mp3","signature":"[\"en\",[[\"B\",\"I usually play football after work, but this term I'm trying a drama class. I wanted to become more confident when speaking to groups. The class is on Thursday, not Tuesday as the website first said. I expected to learn lines immediately, but we began with movement games. They felt strange at first. Now I enjoy them because nobody worries about making mistakes. I still find remembering people's names harder than performing.\",\"male\"]]]"},"b98e0528":{"file":"englisch/lesson-01-2-b98e0528.mp3","signature":"[\"en\",[[\"A\",\"My book group normally meets at the library, but we're meeting online while the building is being repaired. I thought I would dislike it because I spend all day at a computer. However, more members can join now, including a friend who moved away. We discuss one novel each month. We don't choose books by voting; each member takes a turn. The next discussion is on the twelfth, and I'm leading it for the first time.\",\"female\"]]]"},"c2014d24":{"file":"englisch/lesson-02-1-c2014d24.mp3","signature":"[\"en\",[[\"A\",\"I've been a library assistant for five years. I started after completing a history degree, and I expected it to be a temporary job. However, I discovered that helping people find information was more satisfying than I had imagined. Last winter I organised my first digital skills workshop. Only six people came, but all of them asked for another session. I've just been asked to plan a monthly programme. I haven't decided on every topic yet.\",\"female\"]]]"},"1c9b7f93":{"file":"englisch/lesson-02-2-1c9b7f93.mp3","signature":"[\"en\",[[\"B\",\"I applied for a training place in July and had an interview two weeks later. I was nervous because I'd never had an interview in English before. The first question was about teamwork, so I described a project from my previous job rather than giving a general answer. That helped me relax. They've already offered me a place, but I haven't started yet. The training begins in January, and I need to arrange accommodation before then.\",\"male\"]]]"},"381771d0":{"file":"englisch/lesson-03-1-381771d0.mp3","signature":"[\"en\",[[\"B\",\"We need to change our dinner booking. Two colleagues can't come, so there will be five of us instead of seven. The restaurant can keep our table, but they need us to arrive at half past six rather than seven. I asked about vegetarian food, and they have several choices. They also said we should mention any allergies when we order. I'm going to phone again because I'd prefer to check those details before we arrive.\",\"male\"]]]"},"8bcb74e9":{"file":"englisch/lesson-03-2-8bcb74e9.mp3","signature":"[\"en\",[[\"A\",\"I thought the cooking class would be mainly demonstrations, but everyone prepares a complete meal in pairs. This week we made soup using vegetables that shops would otherwise throw away. I was surprised how fresh they were. We didn't follow exact quantities; the teacher wanted us to taste and adjust the seasoning. The best part was eating together afterwards. Next time I'd bring a container, because we made much more than we could eat.\",\"female\"]]]"},"42a788cc":{"file":"englisch/lesson-04-1-42a788cc.mp3","signature":"[\"en\",[[\"A\",\"I was looking for a museum when the rain started. I went into a small shop to ask for directions, but the owner thought I wanted to buy an umbrella. While he was showing me several, I noticed a photograph of the museum behind him and pointed at it. He laughed and explained that it had moved across town. Fortunately, his daughter was going that way and offered to show me the right bus stop.\",\"female\"]]]"},"35cd4038":{"file":"englisch/lesson-04-2-35cd4038.mp3","signature":"[\"en\",[[\"B\",\"We were waiting for our luggage when a man took my suitcase by mistake. I followed him, but before I reached him, he opened it and realised it wasn't his. We both laughed because our cases were identical, even down to the green ribbon on the handle. His bag appeared a few minutes later. Afterwards we compared our luggage labels carefully. Since then, I've used a bright orange strap so I can recognise mine more easily.\",\"male\"]]]"},"049823d8":{"file":"englisch/lesson-05-1-049823d8.mp3","signature":"[\"en\",[[\"B\",\"I used to withdraw cash every day when I travelled, but the fees soon added up. Now I check the charges before choosing a machine and take out enough for several days. I still avoid carrying a large amount. Last month I borrowed money from a colleague when my card stopped working. I paid her back the next morning. My main advice is to have a second payment method, rather than depend on one card.\",\"male\"]]]"},"292e7896":{"file":"englisch/lesson-05-2-292e7896.mp3","signature":"[\"en\",[[\"A\",\"The repair shop said I didn't have to pay because the fault was covered by the guarantee. However, they needed my original receipt, and a bank statement wasn't enough. I found it in an old email. They offered a replacement rather than repairing the device, which suited me because I needed it for work. I should have backed up my files earlier; transferring them from the damaged device was the only difficult part.\",\"female\"]]]"},"9e1e1831":{"file":"englisch/lesson-06-1-9e1e1831.mp3","signature":"[\"en\",[[\"A\",\"I wanted to cycle to work, but I thought the hills would be too difficult. A colleague showed me a route beside the canal. It's slightly longer than the main road, yet much flatter and quieter. At first I wasn't fast enough to get to work without leaving early. After a few weeks, the journey became easier. I still take the bus when it's icy, but I prefer cycling because I arrive feeling more awake.\",\"female\"]]]"},"93ffbdfe":{"file":"englisch/lesson-06-2-93ffbdfe.mp3","signature":"[\"en\",[[\"B\",\"Our team compared two walking routes for the weekend. The coastal path has better views, but it's too exposed if the wind is strong. The forest route is less spectacular, although it has enough shelter and several places to stop. We chose the forest this time because one member is recovering from an injury. We can still enjoy the coast another month. The important thing was finding a route everyone could manage, rather than choosing the most dramatic one.\",\"male\"]]]"},"383617a8":{"file":"englisch/lesson-07-1-383617a8.mp3","signature":"[\"en\",[[\"B\",\"The council may close our street to traffic on summer weekends. I support the idea because children could play outside safely. However, the plan hasn't been approved yet. If it goes ahead, deliveries will use the side road. Residents won't lose access to their garages. The council is asking for comments by Thursday, and I intend to mention the need for clearer signs.\",\"male\"]]]"},"a08c100f":{"file":"englisch/lesson-07-2-a08c100f.mp3","signature":"[\"en\",[[\"A\",\"I thought the guided tour would be too tiring, but there are several stops. If anyone needs a break, the guide waits. We might take the shorter route if the weather is hot. The starting point has changed from the library to the town hall. You don't need to print your ticket. Just show the confirmation on your phone when you arrive.\",\"female\"]]]"},"c718849c":{"file":"englisch/lesson-08-1-c718849c.mp3","signature":"[\"en\",[[\"A\",\"I bought a second-hand table from a woman whose parents had owned a café. The table was scratched, but it was made of solid wood. I sanded it and painted the legs blue. It now stands in my kitchen, where friends gather when I cook. The seller asked for a photo after the work was finished. She was pleased that it would still be used for sharing meals.\",\"female\"]]]"},"dd7b8040":{"file":"englisch/lesson-09-1-dd7b8040.mp3","signature":"[\"en\",[[\"B\",\"I forgot a friend's birthday and felt terrible when she mentioned it. I apologised immediately, but I didn't want to invent an excuse. I explained that I'd been distracted and offered to take her for lunch. She wasn't angry; she'd mainly wondered whether her invitation had reached me. We checked and found it in my email's unwanted messages folder. Now I check that folder regularly.\",\"male\"]]]"},"d98df1c8":{"file":"englisch/lesson-09-2-d98df1c8.mp3","signature":"[\"en\",[[\"A\",\"I expected the presentation to be frightening because I'm uncomfortable speaking to large groups. In fact, the audience asked friendly questions, and I began to enjoy explaining my project. I was disappointed that the slides stopped working, but describing the ideas without them made me feel more confident. Afterwards my manager said the talk had been clearer than the rehearsal. That was surprising, and very encouraging.\",\"female\"]]]"},"0a3d9ab8":{"file":"englisch/lesson-10-1-0a3d9ab8.mp3","signature":"[\"en\",[[\"A\",\"Our dinner plan has changed. Tom can't finish work before seven, so we're meeting at eight instead of six thirty. I've already changed the table reservation. We can stay until ten, when the restaurant closes. Please confirm by lunchtime whether you're coming, because they need the final number. I'm going to walk there, but I'll get a taxi home if the weather turns bad.\",\"female\"]]]"},"4d4629c8":{"file":"englisch/lesson-10-2-4d4629c8.mp3","signature":"[\"en\",[[\"B\",\"I booked a room for a conference, but the event has moved online. I expected to lose the payment because I'd chosen the cheapest rate. Reception couldn't offer a refund, yet they allowed me to move the booking to another date within six months. That suited me because I wanted a holiday later. I had to confirm the new dates by Monday. It was worth asking politely rather than assuming there was no solution.\",\"male\"]]]"},"0911ed37":{"file":"englisch/lesson-11-1-0911ed37.mp3","signature":"[\"en\",[[\"B\",\"The first room I viewed was spacious, but I'd have to share with four other people. The second was smaller and quieter, with only one flatmate. If I worked at home every day, I'd choose the larger room for a desk. Since I'm usually out, privacy matters more. I've asked for a second viewing of the smaller place before paying any deposit.\",\"male\"]]]"},"b1846713":{"file":"englisch/lesson-11-2-b1846713.mp3","signature":"[\"en\",[[\"A\",\"Our building has a shared courtyard which nobody used much. We suggested adding plants and a table, but several residents worried about noise. Instead of arguing, we agreed on quiet hours and a three-month trial. If it became a problem, we'd change the arrangement. So far, people mainly use it for reading and chatting. The trial hasn't ended, but even the residents who were doubtful have helped with the plants.\",\"female\"]]]"},"dc96b378":{"file":"englisch/lesson-12-1-dc96b378.mp3","signature":"[\"en\",[[\"A\",\"My grandfather taught himself to use a computer at seventy. He wanted to keep in touch with relatives rather than read the news. At first he found the screen confusing, but he refused to give up. Now he helps other people at the library. He always explains that being a beginner isn't embarrassing. Watching him has encouraged me to try a course which I had thought I was too old to join.\",\"female\"]]]"},"7f4806b1":{"file":"englisch/lesson-12-2-7f4806b1.mp3","signature":"[\"en\",[[\"B\",\"Our village is famous for an artist who painted the surrounding hills. Visitors often ask where he studied, but he didn't attend art school. He worked in a garage and painted in his free time. A neighbour persuaded him to show his pictures at a local fair. He sold only one, yet that was enough to make him continue. The museum now displays his work alongside paintings by more widely known artists.\",\"male\"]]]"},"0acfe927":{"file":"englisch/lesson-13-1-0acfe927.mp3","signature":"[\"en\",[[\"B\",\"I used to store every photo on one laptop. When it stopped working, I thought I'd lost years of memories. A technician managed to recover most files, but not all. She told me to keep a second copy somewhere else. I now back up new pictures once a week. The process takes only a few minutes, and I feel much less worried about another failure.\",\"male\"]]]"},"6399f171":{"file":"englisch/lesson-13-2-6399f171.mp3","signature":"[\"en\",[[\"A\",\"I called the hotel to ask about a charger I'd left behind. The receptionist said the cleaning team had found one, but she needed me to describe it. Mine had a red label, which made it easy to identify. She told me they could post it, although I'd have to pay the delivery charge. I asked her to keep it until Friday because a colleague was staying there and could collect it.\",\"female\"]]]"},"6c1dfb88":{"file":"englisch/lesson-14-1-6c1dfb88.mp3","signature":"[\"en\",[[\"A\",\"Our team debated whether to work from home every day. I enjoy the quiet, but new colleagues need chances to ask quick questions. I suggested keeping two shared office days instead of making everyone choose one extreme. Most people agreed. We will review the arrangement after six weeks. If it makes communication worse, we'll adjust it rather than pretend the first plan must be perfect.\",\"female\"]]]"},"b5740645":{"file":"englisch/lesson-14-2-b5740645.mp3","signature":"[\"en\",[[\"B\",\"I thought the school should spend its spare money on sports equipment. Another parent argued for library books and explained that many children couldn't borrow suitable books nearby. That changed my view. We still disagree about the exact amount, but we now support splitting the budget. Listening to a concrete example helped more than being told my opinion was selfish. I want the final decision to include the children too.\",\"male\"]]]"},"c1788bed":{"file":"englisch/lesson-15-1-c1788bed.mp3","signature":"[\"en\",[[\"B\",\"I wanted an appointment tomorrow, but the clinic offered Friday instead. I didn't assume that was my only option; I asked whether they kept a cancellation list. They do, so I've left my number. The receptionist reminded me to describe any change in my symptoms when I speak to the clinician. She didn't try to diagnose the problem herself. I've written down when it started so I can explain it clearly.\",\"male\"]]]"},"041b3f22":{"file":"englisch/lesson-15-2-041b3f22.mp3","signature":"[\"en\",[[\"A\",\"I saw someone in a coat like my friend's outside the clinic and thought it must be her. Then I remembered she was visiting relatives abroad. It couldn't have been her, after all. Later she sent me a photo of herself by the sea. It reminded me not to treat one familiar detail as proof. Next time I'll check before sending a worried message.\",\"female\"]]]"},"c4103d23":{"file":"englisch/lesson-16-1-c4103d23.mp3","signature":"[\"en\",[[\"A\",\"I asked a staff member where the replacement bus stopped. She explained that it was across the footbridge, but I hadn't noticed the lift. When I asked again, she showed me the accessible route. I was relieved because my suitcase was heavy. The bus left ten minutes later than planned, yet I still reached my connection. Asking a clear follow-up question saved me from struggling up the stairs.\",\"female\"]]]"},"d10a9aea":{"file":"englisch/lesson-16-2-d10a9aea.mp3","signature":"[\"en\",[[\"B\",\"We thought the return ticket would be valid the next morning, but the small print said travel had to finish before midnight. I asked whether we could pay the difference rather than buy entirely new tickets. The clerk explained that an upgrade was possible only before the outward journey started. We hadn't boarded yet, so we changed the tickets. It cost less than I expected, and we could stay overnight without worrying.\",\"male\"]]]"},"094f15f2":{"file":"englisch/lesson-17-1-094f15f2.mp3","signature":"[\"en\",[[\"B\",\"The reporter said the market had been cancelled, but the organiser told me only the outdoor stalls were closed. The indoor section was still open. I'd already promised to meet a friend there, so I called to explain. She asked me to send the exact entrance because construction work had blocked the main door. We met beside the library entrance and had a good afternoon despite the confusion.\",\"male\"]]]"},"5ef57d0b":{"file":"englisch/lesson-17-2-5ef57d0b.mp3","signature":"[\"en\",[[\"A\",\"I had prepared a long explanation for being late, but the interviewer told me not to worry. A fire alarm had delayed everyone. She asked me to take a seat while they checked the building. I was relieved, yet I still explained that I'd left home too late. Afterwards, I decided to plan an earlier arrival next time. An unexpected delay on their side didn't make my planning any better.\",\"female\"]]]"},"15c197be":{"file":"englisch/lesson-18-1-15c197be.mp3","signature":"[\"en\",[[\"A\",\"The charity shop couldn't accept our broken chairs, so I asked whether anyone could repair them. A local volunteer replaced two loose joints. Both chairs are safe now, and they'll be used in the reading room. I had assumed they were worthless because they looked worn. The volunteer explained that repairing strong old furniture can be easier than fixing cheap new pieces. Next time I'll ask before throwing anything away.\",\"female\"]]]"},"cfe5d591":{"file":"englisch/lesson-18-2-cfe5d591.mp3","signature":"[\"en\",[[\"B\",\"Our office has stopped giving out disposable cups. Everyone received a reusable one, but visitors can still borrow clean cups at reception. At first, people complained that washing up would take too long. After a month, most hardly noticed the extra task. The main problem was finding space to dry everything, not the washing itself. A small shelf solved that. We haven't measured all the savings yet, so I wouldn't claim a precise environmental result.\",\"male\"]]]"},"9717fd49":{"file":"englisch/lesson-19-1-9717fd49.mp3","signature":"[\"en\",[[\"B\",\"I volunteered to help at a food collection, expecting to carry boxes all morning. Instead, the organiser asked me to welcome people at the entrance. I was nervous, but another volunteer showed me what to say. After an hour I could manage by myself. We later swapped tasks so she could take a break. I liked that we were trusted to help each other rather than wait for instructions every minute.\",\"male\"]]]"},"6d814983":{"file":"englisch/lesson-19-2-6d814983.mp3","signature":"[\"en\",[[\"A\",\"Our team nearly gave up after the first fundraising event attracted very few people. We found out that another event had been advertised for the same time. Instead of blaming ourselves, we spoke to its organisers and planned a shared afternoon. The second event did better, although we raised less money than we'd hoped. We also met new volunteers, which may be more valuable in the long term.\",\"female\"]]]"},"bac1174a":{"file":"englisch/lesson-20-1-bac1174a.mp3","signature":"[\"en\",[[\"A\",\"I took a spare charger in case my usual one failed during a work trip. I didn't need it, but a colleague did. She had brought the wrong cable. I lent mine to her as long as she returned it before my train left. That worked well, though I labelled both chargers afterwards. Being prepared helped, but keeping track of borrowed equipment mattered too.\",\"female\"]]]"},"e88a1806":{"file":"englisch/lesson-20-2-e88a1806.mp3","signature":"[\"en\",[[\"B\",\"The delivery website said my parcel had arrived, but there was nothing outside. I checked with neighbours before contacting customer service. One had accepted it, but the driver hadn't left a note. I told the company the problem was solved, while asking them to improve the notifications. They apologised and confirmed my suggestion would be passed on. I didn't request a refund for an item I had actually received.\",\"male\"]]]"},"5f120df6":{"file":"englisch/lesson-21-1-5f120df6.mp3","signature":"[\"en\",[[\"B\",\"The notice said the event had been postponed, not cancelled. I nearly threw away my ticket before reading the next line. It explained that tickets would remain valid for the new date and that people who couldn't attend could request a refund. I checked the website rather than rely on an old social media post. The new date suited me, so I kept the ticket.\",\"male\"]]]"},"db8c7f8a":{"file":"englisch/lesson-21-2-db8c7f8a.mp3","signature":"[\"en\",[[\"A\",\"When choosing a tour for my parents, I first looked for one with good reviews. But some popular walks had steep steps, which wouldn't suit them. I read the practical details and found a shorter route with seats along the way. It had fewer reviews but met their needs. I phoned to confirm the surface was suitable in wet weather. They enjoyed it, and we weren't exhausted afterwards.\",\"female\"]]]"},"659af946":{"file":"englisch/lesson-22-1-659af946.mp3","signature":"[\"en\",[[\"A\",\"For my story, I spent too long describing the weather and didn't explain why the main character was worried. When I read it aloud, I noticed the gap. I added one sentence about a missing ticket and shortened the opening. Now the ending makes sense because the reader understands what has been found. Reading aloud didn't catch every grammar mistake, but it helped me hear where the story was confusing.\",\"female\"]]]"},"2f0c7340":{"file":"englisch/lesson-22-2-2f0c7340.mp3","signature":"[\"en\",[[\"B\",\"I wanted my article to recommend a local museum, but my first draft was just a list of rooms. I changed it to explain who would enjoy the visit and included a short example from my own trip. I also mentioned that the upper floor has stairs, so visitors can check access before going. The title is simpler now. I think the article helps a reader make a decision rather than merely repeat the museum brochure.\",\"male\"]]]"},"934d17b7":{"file":"englisch/lesson-23-1-934d17b7.mp3","signature":"[\"en\",[[\"B\",\"In the photo, three people are sitting around a table outdoors. The person on the left is pointing at a map, while another is holding a cup. There are backpacks on the ground, so they might be planning a walk. I can't tell whether they know the area well. In the background, a bus is waiting beside a low building. Everyone seems relaxed, although one person is checking the time.\",\"male\"]]]"},"a90b5e85":{"file":"englisch/lesson-23-2-a90b5e85.mp3","signature":"[\"en\",[[\"A\",\"During our practice discussion, I thought disagreeing would make me sound unfriendly. So I accepted every suggestion, even when I had a useful concern. My partner said that made the conversation harder because she couldn't see what I really thought. Next time I used \\\"I see your point, but...\\\" and explained my reason. We had a more natural discussion and changed our first choice together.\",\"female\"]]]"},"3fb0c057":{"file":"englisch/lesson-24-1-3fb0c057.mp3","signature":"[\"en\",[[\"A\",\"I used to choose answers because a familiar word appeared in an option. My teacher asked me to explain the evidence each time. I discovered that wrong answers often repeated words while changing the meaning. Now I listen for the speaker's final decision, especially after phrases like \\\"actually\\\" or \\\"instead\\\". My scores have become more consistent, but I also understand the conversations better, which matters more to me.\",\"female\"]]]"},"9dbb3bff":{"file":"englisch/lesson-24-2-9dbb3bff.mp3","signature":"[\"en\",[[\"B\",\"I've planned a month of practice with a friend. On Mondays we'll exchange short emails, and on Thursdays we'll discuss a photo for a minute each. We agreed to ask for clarification before correcting every small error. If an idea is unclear, we'll explain what confused us. At the end of the month, we'll compare our first and last recordings and choose the next skill to work on.\",\"male\"]]]"}}};
